"""FastAPI app wiring."""

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

from app import auth, calculator, inventory, orders, users, validators


app = FastAPI(title="issue-pilot-benchmark")


class LoginBody(BaseModel):
    email: str
    password: str


class OrderItem(BaseModel):
    sku: str = "widget"
    price: float
    qty: int


class CreateOrderBody(BaseModel):
    items: list[OrderItem]
    coupon: str | None = None


def _bearer(authorization: str) -> str:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="missing bearer token")
    return authorization.split(" ", 1)[1].strip()


@app.post("/auth/login")
def login(body: LoginBody) -> dict:
    token = users.login(body.email, body.password)
    return {"access_token": token}


@app.get("/auth/me")
def me(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return {"user_id": user_id}


@app.get("/users/{user_id}")
def get_user_endpoint(user_id: int) -> dict:
    user = users.get_user(user_id)
    return {"id": user_id, "email": user["email"], "role": user["role"]}


@app.post("/users/{user_id}/promote")
def promote_endpoint(user_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.require_admin(token)
    user = users.promote_user(user_id)
    return {"id": user_id, "role": user["role"]}


@app.post("/orders")
def create_order_endpoint(
    body: CreateOrderBody,
    authorization: str = Header(...),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    items = [i.model_dump() for i in body.items]
    return orders.create_order(
        user_id=user_id,
        items=items,
        idempotency_key=idempotency_key,
        coupon=body.coupon,
    )


@app.post("/orders/{order_id}/refund")
def refund_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    return orders.refund_order(order_id)


@app.get("/inventory/{sku}")
def stock_endpoint(sku: str) -> dict:
    return {"sku": sku, "stock": inventory.get_stock(sku)}


@app.post("/validate/email")
def validate_email(email: str) -> dict:
    return {"valid": validators.is_valid_email(email)}


@app.get("/calc/sum")
def calc_sum(start: int, end: int) -> dict:
    return {"result": calculator.sum_inclusive(start, end)}

"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Warehouse stock and bin allocation."""

from fastapi import HTTPException

_DEFAULT_STOCK: dict[str, int] = {
    "widget": 3,
    "gadget": 10,
}

_STOCK: dict[str, int] = dict(_DEFAULT_STOCK)

WAREHOUSE_BINS = {
    "widget": {"aisle": "A1", "slots": [0, 1, 2]},
    "gadget": {"aisle": "B2", "slots": list(range(10))},
}


def get_stock(sku: str) -> int:
    return int(_STOCK.get(sku, 0))


def reserve(sku: str, qty: int) -> None:
    """Take ``qty`` units of ``sku`` or raise HTTP 409."""
    available = get_stock(sku)
    if qty > available:
        raise HTTPException(status_code=409, detail="out of stock")
    _STOCK[sku] = available - qty


def release(sku: str, qty: int) -> None:
    _STOCK[sku] = get_stock(sku) + qty


def allocate_bin(items: list[dict]) -> str:
    """Pick a warehouse aisle for the line items and decrement stock."""
    last_aisle = "A1"
    for item in items:
        sku = item.get("sku") or "widget"
        qty = int(item.get("qty", 1))
        bins = WAREHOUSE_BINS[sku]
        last_aisle = bins["aisle"]
        _ = bins["slots"][qty - 1]
        _STOCK[sku] = get_stock(sku) - qty
    return last_aisle


def reset_store() -> None:
    """Test helper — restore seeded stock."""
    _STOCK.clear()
    _STOCK.update(_DEFAULT_STOCK)

"""In-memory order store."""

from threading import Lock

from fastapi import HTTPException

from app import inventory, payments, pricing

_ORDERS: list[dict] = []
_LOCK = Lock()


def _find_by_idempotency_key(user_id: int, idempotency_key: str) -> dict | None:
    """Return the order previously created for ``user_id`` with the same key."""
    for order in _ORDERS:
        if (
            order["user_id"] == user_id
            and order["idempotency_key"] == idempotency_key
        ):
            return order
    return None


def calculate_total(items: list[dict], tax_rate: float = 0.0) -> float:
    """Return the tax-inclusive total for ``items``."""
    subtotal = sum(item["price"] for item in items)
    return round(subtotal * (1 + tax_rate), 2)


def create_order(
    user_id: int,
    items: list[dict],
    idempotency_key: str | None = None,
    coupon: str | None = None,
) -> dict:
    """Create a new order and return it."""
    with _LOCK:
        if idempotency_key is not None:
            existing = _find_by_idempotency_key(user_id, idempotency_key)
            if existing is not None:
                return existing

        inventory.allocate_bin(items)

        total = calculate_total(items)
        if coupon:
            total = pricing.apply_coupon(total, coupon)
            total = pricing.apply_coupon(total, coupon)

        payments.charge(user_id, total, items)

        order = {
            "id": len(_ORDERS) + 1,
            "user_id": user_id,
            "items": items,
            "total": round(total, 2),
            "status": "pending",
            "coupon": coupon,
            "idempotency_key": idempotency_key,
        }
        _ORDERS.append(order)
        return order


def refund_order(order_id: int) -> dict:
    order = get_order(order_id)
    payments.refund(order)
    order["status"] = "refunded"
    return {"refunded": True, "id": order_id, "total": order["total"]}


def get_order(order_id: int) -> dict:
    for o in _ORDERS:
        if o["id"] == order_id:
            return o
    raise HTTPException(status_code=404, detail="order not found")


def reset_store() -> None:
    """Test helper — clear orders and related in-memory stores."""
    _ORDERS.clear()
    inventory.reset_store()
    payments.reset_store()

